import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/guide/faq.md","filePath":"zh-CN/guide/faq.md","lastUpdated":1793173149000}`),a={name:`zh-CN/guide/faq.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h1><p>问：Sudoku 是什么？</p><p>答：Sudoku 是经典的逻辑数字填格谜题，专为现代 Apple 设备重新打造。填满 9×9 的网格，使每一行、每一列和每个 3×3 宫都恰好包含 1–9 各一次。它是一款通用 App，支持 iPhone、iPad 和 Mac，并支持 iCloud 同步。</p><p>问：支持哪些设备？</p><p>答：Sudoku 是一款通用 App，针对 iPhone、iPad 和 Mac 优化，提供原生控件和清晰的 Retina 显示效果。它需要 iOS/iPadOS 16.0 或更高版本，以及 macOS 15.0（Sequoia）或更高版本。一次购买即可在所有受支持的设备上使用。</p><p>问：如何下载并安装 Sudoku？</p><p>答：请从 App Store 下载 Sudoku：<a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793606018</a> —— 这款通用 App 可在 iPhone、iPad 和 Mac 上使用。</p><p>问：Sudoku 需要联网吗？</p><p>答：核心玩法 100% 离线——解题不需要网络。需要联网的可选功能包括 iCloud 同步（用于跨设备同步进度）、Game Center（排行榜/成就），以及设置中的“更多 App”板块。</p><p>问：有广告或 App 内购买吗？</p><p>答：没有。Sudoku 完全没有广告，没有弹窗，没有 App 内购买，也不会打断你。只有纯粹、专注的解谜乐趣。</p><p>问：有哪些难度级别？</p><p>答：五个难度级别，已知格数量各不相同：</p><ul><li><strong>简单</strong> —— 45 个已知格（非常适合新手）</li><li><strong>中等</strong> —— 36 个已知格（均衡的挑战）</li><li><strong>困难</strong> —— 31 个已知格（需要推理技巧）</li><li><strong>专家</strong> —— 27 个已知格（适合有经验的解题者）</li><li><strong>大师</strong> —— 24 个已知格（终极挑战）</li></ul><p>每道题目都是独立生成的——你不会两次玩到同一道题。</p><p>问：我的游戏数据会在设备间同步吗？</p><p>答：会！登录 iCloud 后，你的游戏存档、统计数据、设置和每日挑战进度会通过 CloudKit 自动同步到你的所有 Apple 设备。</p><p>问：退出后 Sudoku 会保存进度吗？</p><p>答：会。当前对局会自动保存，你可以从上次离开的地方继续。主界面会显示一张带当前对局的“继续”卡片。</p><p>问：如何更新应用？</p><p>答：App Store 用户会自动收到更新。如需手动检查，请打开 App Store，进入“账户 → 更新”页面。</p><p>问：如何报告 bug 或提出功能建议？</p><p>答：请在项目仓库中提交 issue，并附上设备类型、iOS/macOS 版本、Sudoku 版本、复现步骤，以及可用的截图。</p><p>问：可以自定义外观吗？</p><p>答：可以！你可以在设置中选择 8 种精美主题（经典、午夜、纸张、森林、海洋、日落、薰衣草、玫瑰），也可以开关音效。</p><p>问：支持多少种语言？</p><p>答：25 种语言，可在运行时切换，无需重启：英语、简体中文、繁体中文、日语、韩语、法语、德语、西班牙语、意大利语、俄语、葡萄牙语、荷兰语、越南语、泰语、印地语、土耳其语、希腊语、芬兰语、挪威语、丹麦语、匈牙利语、印尼语、马来语、乌克兰语，以及德语（瑞士）。</p><p>问：Mac 上的键盘快捷键有哪些？</p><p>答：<code>⌘N</code> 开始新游戏，<code>⌘Z</code> 撤销，<code>⌘1</code> 到 <code>⌘5</code> 分别以各难度级别（从简单到大师）开始新游戏。</p><p>问：可以打印题目吗？</p><p>答：可以！在 Mac 上使用打印功能，即可生成任意难度的可打印题目，还可以选择附上答案。</p><p>如果需要更多解答，请在仓库中提交 issue，或查阅完整文档。</p>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};